

const IMG={"logo":"/assets/logo.png","hero":"/assets/hero.jpg","foam":"/assets/foam.jpg","water":"/assets/water.jpg","dj":"/assets/dj.jpg","jamaica":"/assets/jamaica.jpg","cabana":"/assets/cabana.jpg"};
document.getElementById('logo').src=IMG.logo;
const KEY='skinzBubblesFullDemoV1';let initial={applications:[],session:null,host:false,favorites:[],ticket:'',journey:0,view:'Home',ambView:'start',guide:'',downloadCount:0,announcements:[{id:'welcome',title:'Welcome to the team!',body:'Skinz & Bubbles 2027 is coming to Kingston. Start with your bio and share the excitement. Welcome to the ambassador team!',date:'Announcement'}]};
function load(){try{let d=JSON.parse(localStorage.getItem(KEY)||'{}');return {...initial,...d}}catch{return {...initial}}}
let db=load();db.announcements=db.announcements||initial.announcements;function save(){const safe={...db,guests:[],guestSession:null};localStorage.setItem(KEY,JSON.stringify(safe))};let app=document.getElementById('app');
const E=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function flash(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.remove('hide');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>t.classList.add('hide'),2900)}
function navigate(view){db.view=view;save();render();document.getElementById('app').scrollTo(0,0)}function amb(view){db.ambView=view;db.view='Ambassadors';save();render();document.getElementById('app').scrollTo(0,0)}
function showHelp(){flash('Explore Skinz & Bubbles. Ticket sales and live accounts are not available in this preview.')}
function photo(name,title,description='',cls=''){return `<div class="photo ${cls}" style="background-image:linear-gradient(0deg,#03193222,#03193220),url('${IMG[name]}')"><div><h2 style="margin:0 0 8px">${title}</h2><p class="sub" style="margin:0">${description}</p></div></div>`}
function btn(label,fn,style=''){return `<button class="btn ${style}" onclick="${E(fn)}">${label}</button>`}
function countdown(){const m=Date.parse('2027-07-31T12:00:00-05:00')-Date.now();let d=Math.max(0,Math.ceil(m/86400000));return d}
function home(){return `${photo('hero','Welcome to the Bubbles','Your ultimate summer experience in Kingston, Jamaica.','hero')}<div class="stats"><div class="stat"><strong>${countdown()}</strong><span>DAYS TO GO</span></div><div class="stat"><strong>2027</strong><span>JULY 31</span></div><div class="stat"><strong>JA</strong><span>KINGSTON</span></div></div><div class="actions">${btn('EXPLORE THE EXPERIENCE →',"navigate('Experience')")}${btn('CHOOSE YOUR EXPERIENCE →',"navigate('Tickets')",'aqua')}</div><section class="section"><div class="eyebrow">THE SUMMER STARTS HERE</div><h2>More than a party. Make memories.</h2><p class="sub">The fashion, the friends, the music and the Jamaican culture make every moment part of the story.</p><div class="cards">${['foam','water','cabana','jamaica'].map((n,i)=>`<div>${photo(n,['FOAM BLAST','WATER RUSH','VIP LIFESTYLE','DISCOVER JAMAICA'][i])}<div class="actions">${btn('EXPLORE →',`navigate('${i===3?'Jamaica':'Experience'}')`,'small aqua')}</div></div>`).join('')}</div></section><div class="panel"><h2>Become part of the team 🫧</h2><p class="sub">Apply to represent Skinz & Bubbles 2027 and get your own ambassador dashboard.</p>${btn('JOIN THE AMBASSADOR TEAM →',"amb('apply')",'yellow')}</div>`}
const steps=[['The Arrival','Touch down in Kingston. Your summer is officially on.','jamaica'],['The Music','Feel the DJs, dancehall energy and your people.','dj'],['The Foam Blast','The signature moment. A sea of bubbles and sunshine.','foam'],['The VIP Lifestyle','Make space for your crew and the premium experience.','cabana'],['The Memories','The videos, smiles and stories you take home.','hero']];
function experience(){let i=db.journey;return `<div class="eyebrow">LIVE THE MOMENT</div><h1>The <em>Experience</em></h1><p class="sub">Explore the moments that make Skinz & Bubbles unforgettable.</p>${photo(steps[i][2],steps[i][0],steps[i][1],'hero')}<div class="panel"><div class="eyebrow">MOMENT ${i+1} OF ${steps.length}</div><div class="progress"><b style="width:${(i+1)*20}%"></b></div><div class="actions">${btn(db.favorites.includes(steps[i][0])?'♥ SAVED':'♡ SAVE TO FAVORITES',`toggleFavorite(${JSON.stringify(steps[i][0])})`,'ghost')}${btn(i<4?'NEXT MOMENT →':'EXPLORE TICKETS →',i<4?'nextMoment()':"navigate('Tickets')",'aqua')}${i?btn('← BACK','prevMoment()','ghost'):''}</div></div><h2 class="section">Experience zones</h2><div class="cards">${[['FOAM BLAST','foam'],['WATER RUSH','water'],['MUSIC & VIBES','dj'],['VIP & CABANAS','cabana']].map(([n,img],j)=>`<div class="card ${j%3===1?'pink':j%3===2?'yellow':''}"><h3>${n}</h3><p>Tap to explore this ${n.toLowerCase()} moment.</p>${btn('EXPLORE',`setMoment(${[2,2,1,3][j]})`,'small ghost')}</div>`).join('')}</div>`}
function nextMoment(){db.journey=Math.min(4,db.journey+1);save();render()};function prevMoment(){db.journey=Math.max(0,db.journey-1);save();render()};function setMoment(i){db.journey=i;save();render();document.getElementById('app').scrollTo(0,0)};function toggleFavorite(s){db.favorites=db.favorites.includes(s)?db.favorites.filter(x=>x!==s):[...db.favorites,s];save();render();flash('Saved moments updated')}
const guides={activities:[['Kingston culture','Explore Kingston’s music, arts and neighborhoods.'],['Island experiences','Plan downtime and day trips around your festival visit.']],food:[['Jamaican flavors','Try authentic jerk, patties and traditional Jamaican cooking.'],['Local favorites','Discover local spots as the guide is updated.']],stay:[['Kingston hotels','Compare accommodation near your planned activities.'],['Apartments & villas','Look for group-friendly stays and verified listings.']],travel:[['Airport arrival','Plan your arrival in Kingston and your transfer in advance.'],['Getting around','Use trusted, licensed transport and confirm arrangements.']]};
function jamaica(){let selected=db.guide;return `<div class="eyebrow">LIVE THE ISLAND</div><h1>Discover <em>Jamaica</em></h1><p class="sub">THE CULTURE • THE PEOPLE • THE FOOD • THE VIBES</p>${photo('jamaica','Your island. Your summer.','Explore Jamaica beyond the festival.','hero')}<div class="cards">${[['activities','THINGS TO DO','aqua'],['food','JAMAICAN FOOD','yellow'],['stay','HOTELS & STAYS','pink'],['travel','TRAVEL GUIDE','aqua']].map(([k,n,c])=>`<div class="card ${c==='aqua'?'':c}"><h3>${n}</h3><p>Explore the ${n.toLowerCase()} guide.</p>${btn('OPEN GUIDE →',`openGuide('${k}')`,'small ghost')}</div>`).join('')}</div>${selected?`<div class="panel"><button class="back" onclick="openGuide('')">← Close guide</button><h2>${{activities:'Things to do',food:'Jamaican food',stay:'Hotels and stays',travel:'Travel guide'}[selected]}</h2>${guides[selected].map(([a,b])=>`<div class="guidecard"><h3>${a}</h3><p>${b}</p></div>`).join('')}<p class="muted">Travel partners and recommended places will be announced as details are confirmed.</p></div>`:''}`}
function openGuide(k){db.guide=k;save();render();if(k)document.querySelector('.panel')?.scrollIntoView({behavior:'smooth',block:'center'})}
function lineup(){return `<div class="eyebrow">THE SOUND OF THE SUMMER</div><h1>Music & <em>Lineup</em></h1>${photo('dj','Feel the music','Jamaica’s finest energy. Official lineup announcements coming soon.','hero')}<div class="panel"><h2>Official lineup coming soon</h2><p class="sub">Artist names and set times have not been confirmed. Check back for the official lineup.</p><div class="actions">${btn(db.favorites.includes('Lineup updates')?'♥ UPDATES SAVED':'♡ SAVE LINEUP UPDATES',"toggleFavorite('Lineup updates')",'aqua')}${btn('EXPLORE THE MUSIC MOMENT →',"setMoment(1)")}</div><div class="notice">Lineup alerts will be available when notifications launch.</div></div>`}
const ticketTypes=[['GENERAL ADMISSION','Full festival energy',''],['VIP EXPERIENCE','A more premium festival day','pink'],['GROUP DEALS','Bring your whole crew','yellow'],['CABANAS','Your private premium space','']];
function tickets(){return `<div class="eyebrow">PICK YOUR EXPERIENCE</div><h1>Get <em>Tickets</em></h1><p class="sub">Choose your ticket experience. Create an account to continue to checkout.</p><div class="cards">${ticketTypes.map(([n,d,c])=>`<div class="card ${c}"><h3>${n} ${db.ticket===n?'✓':''}</h3><p>${d}</p>${btn(db.ticket===n?'SELECTED':'SELECT EXPERIENCE',`selectTicket('${n}')`,'small ghost')}</div>`).join('')}</div>${db.ticket?`<div class="panel"><div class="eyebrow">YOUR SELECTED EXPERIENCE</div><h2>${db.ticket}</h2><p class="sub">Your selection is saved while you sign in or create an account.</p><div class="actions">${btn('CONTINUE TO CHECKOUT →','testCheckout()','yellow')}${btn('CHANGE SELECTION',"clearTicket()",'ghost')}</div><div class="notice">Ticket sales are not open in this preview. No payment will be collected.</div></div>`:''}${photo('cabana','VIP & Cabanas','Your summer, elevated.')} `}
function selectTicket(n){db.ticket=n;save();render();flash(n+' selected')};function clearTicket(){db.ticket='';save();render()};function testCheckout(){flash('Your selection is saved. Ticket checkout will be available when sales open.')}
const tasks=[['Add “Skinz & Bubbles Ambassador” to your Instagram bio','Bio updated'],['Add the official ticket link to your bio','Ticket link added'],['Share the official announcement on your story','Story shared'],['Share one festival post or Reel','Post shared'],['Invite friends to follow Skinz & Bubbles','Friends invited']];
function application(){return `<button class="back" onclick="amb('start')">← Ambassador home</button><div class="eyebrow">APPLY & CREATE ACCOUNT</div><h1>Become an <em>Ambassador</em></h1><p class="sub">Set up your return login now, so you can check your approval status anytime.</p><div class="panel"><form id="applyForm" class="form" onsubmit="submitApplication(event)"><label>Full name *<input name="name" maxlength="70" required placeholder="Your full name"></label><label>Email *<input name="email" type="email" maxlength="120" required placeholder="you@example.com"></label><label>Phone *<input name="phone" type="tel" maxlength="30" required placeholder="Your phone number"></label><label>Instagram handle *<input name="instagram" maxlength="45" required placeholder="@yourhandle"></label><label>TikTok handle (optional)<input name="tiktok" maxlength="45" placeholder="@yourhandle"></label><label>Why do you want to join? (optional)<textarea name="why" maxlength="400" placeholder="Tell us a little about yourself"></textarea></label><div class="signup-divider"><strong>YOUR LOGIN DETAILS</strong><p>You'll use these to return and check your application.</p></div><label>Create username *<input name="username" minlength="3" maxlength="25" pattern="[A-Za-z0-9_]{3,25}" required autocomplete="username" placeholder="islandambassador"></label><label>Create a 6-digit PIN *<input name="pin" type="password" inputmode="numeric" minlength="6" maxlength="6" pattern="[0-9]{6}" autocomplete="new-password" required placeholder="Six numbers"></label><label>Confirm your PIN *<input name="confirmPin" type="password" inputmode="numeric" minlength="6" maxlength="6" pattern="[0-9]{6}" autocomplete="new-password" required placeholder="Repeat PIN"></label><div class="amb-consent"><h3>Before you submit</h3><p>Please review the program terms and how your information will be handled.</p><div class="amb-legal-links"><button type="button" class="amb-legal-link" onclick="openAmbLegal('terms')">Read Ambassador Terms &amp; Conditions ↗</button><button type="button" class="amb-legal-link" onclick="openAmbLegal('privacy')">Read Privacy Notice ↗</button></div><label class="amb-agree" for="amb-terms-agree"><input id="amb-terms-agree" type="checkbox" name="termsAgree" value="yes" required><span>I have read and agree to the <button type="button" class="inline-legal" onclick="openAmbLegal('terms')">Ambassador Terms &amp; Conditions</button> and acknowledge the <button type="button" class="inline-legal" onclick="openAmbLegal('privacy')">Privacy Notice</button>. <strong>*</strong></span></label><p class="amb-consent-help">You must agree before submitting. These policies are preliminary and will be finalized before launch.</p></div><button type="submit" class="btn yellow">CREATE ACCOUNT &amp; SUBMIT APPLICATION</button></form><div class="notice">After applying, your status will show PENDING. Once approved, the same login opens your ambassador dashboard.</div><p class="muted">For this preview, use a PIN you do not use anywhere else. Accounts are saved only in this browser.</p></div><div class="actions">${btn('ALREADY APPLIED? SIGN IN',"amb('login')",'ghost')}</div>`}

const AMB_LEGAL_DRAFT_VERSION='demo-draft-2026-11-22';
function openAmbLegal(kind){
  const title=kind==='terms'?'Ambassador Terms & Conditions':'Ambassador Privacy Notice';
  const body=kind==='terms'?`<p><strong>Draft for interactive testing only.</strong> The official Skinz & Bubbles Ambassador Program terms have not been finalized or approved for public use.</p><h3>Program participation</h3><p>Ambassador applications are subject to review. An application does not guarantee selection. Approved ambassadors may receive promotional tasks and access to brand materials.</p><h3>Promotion and conduct</h3><p>Ambassadors should use only authorized assets, make accurate claims, respect others, follow applicable social platform rules, and disclose promotional relationships when required.</p><h3>Content and rewards</h3><p>Submitted links may be reviewed to verify task completion. Any rewards, referral arrangements, eligibility requirements, and termination rules must be clearly published in the final program terms before launch.</p><h3>Changes and contact</h3><p>These sample terms do not create a live ambassador agreement. The host must replace them with reviewed, dated official terms before accepting real applications.</p>`:
  `<p><strong>Draft for interactive testing only.</strong> This demo stores sample application details, login PINs, and test progress in this browser's local storage. It does not securely store real account details or transmit an application to a server.</p><h3>Information entered</h3><p>The application asks for your name, email, phone, Instagram and optional TikTok handle, username, and test PIN. The demo also records the date and version of your acknowledgement.</p><h3>How demo data is used</h3><p>Sample information is used only to demonstrate application review, status checks, assignments, referrals, and announcements in this browser. Host Portal can view test information on this device.</p><h3>Before the real launch</h3><p>The live Privacy Policy must explain the actual operator, purposes, lawful processing, retention, sharing, security, deletion rights, and contact details. Do not enter personal or sensitive information into this demo.</p>`;
  const existing=document.getElementById('amb-legal-modal');if(existing)existing.remove();
  const el=document.createElement('div');el.id='amb-legal-modal';el.className='amb-modal-shade';el.setAttribute('role','presentation');
  el.innerHTML=`<section class="amb-modal" role="dialog" aria-modal="true" aria-labelledby="amb-legal-heading"><div class="amb-modal-header"><div><small>SKINZ & BUBBLES • POLICY INFORMATION</small><h2 id="amb-legal-heading">${title}</h2></div><button type="button" onclick="closeAmbLegal()" class="amb-modal-x" aria-label="Close policy">✕</button></div><div class="amb-modal-body">${body}</div><div class="amb-modal-foot"><button type="button" onclick="closeAmbLegal()" class="btn aqua">BACK TO APPLICATION</button></div></section>`;
  el.addEventListener('click',e=>{if(e.target===el)closeAmbLegal()});document.body.appendChild(el);el.querySelector('.amb-modal-x').focus();
}
function closeAmbLegal(){document.getElementById('amb-legal-modal')?.remove()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeAmbLegal()});

function submitApplication(e){e.preventDefault();let f=new FormData(e.target);if(f.get('termsAgree')!=='yes'){flash('Please accept the Ambassador Terms & Conditions before submitting.');document.getElementById('amb-terms-agree')?.focus();return}let email=String(f.get('email')).trim().toLowerCase(),username=String(f.get('username')).trim().toLowerCase(),pin=String(f.get('pin')).trim(),confirmation=String(f.get('confirmPin')).trim();if(db.applications.some(a=>a.email===email)){flash('This email already has an application. Please sign in.');return}if(db.applications.some(a=>a.username===username)){flash('Username taken. Please choose a different one.');return}if(!/^[a-z0-9_]{3,25}$/.test(username)||!/^\d{6}$/.test(pin)||pin!==confirmation){flash('Choose a username and enter matching six-digit PINs.');return}let a={id:'SB'+Date.now()+Math.floor(Math.random()*10000),name:String(f.get('name')).trim(),email,phone:String(f.get('phone')).trim(),instagram:String(f.get('instagram')).trim(),tiktok:String(f.get('tiktok')).trim(),why:String(f.get('why')).trim(),username,demoPin:pin,status:'pending',tasks:[],proofs:{},proofStatus:{},readAnnouncements:[],referralCount:0,date:new Date().toLocaleDateString(),termsAcceptedAt:new Date().toISOString(),termsVersion:'demo-draft-2026-11-22',privacyAcknowledgedAt:new Date().toISOString()};db.applications.push(a);db.session=a.id;save();amb('status');flash('Application submitted. You can return anytime to check your status.')}

function current(){let a=db.applications.find(a=>a.id===db.session);return a&&a.status!=='disabled'&&a.status!=='rejected'?a:null}
function ambassadorHome(){return `<section class="amb-clean" aria-label="Ambassador Hub"><div class="amb-intro"><div class="amb-tag"><span class="amb-dot"></span> SKINZ & BUBBLES AMBASSADORS <span class="amb-year">2027</span></div><h1>Be part of<br><em>the Bubbles.</em></h1><p>Join the team bringing Jamaica’s ultimate foam experience to life. Share the vibes and connect your crew.</p></div><div class="amb-feature"><div class="amb-feature-art" style="background-image:linear-gradient(0deg,rgba(4,29,56,.66),rgba(4,29,56,.03) 63%),url('${IMG.hero}')"><span class="amb-feature-stamp">KINGSTON, JAMAICA • JULY 31, 2027</span></div></div><div class="amb-cta"><div class="amb-section-title"><span>START HERE</span><h2>Become an ambassador</h2><p>Create your account and send your application in one step.</p></div><button class="amb-primary" onclick="amb('apply')">APPLY TO JOIN <span aria-hidden="true">→</span></button><button class="amb-secondary" onclick="amb('login')">Already applied? Sign in to check your status →</button></div><div class="amb-simple-steps"><div><span class="amb-step-num">01</span><strong>Create account</strong><small>Sign up when you apply</small></div><div><span class="amb-step-num">02</span><strong>Check status</strong><small>Sign in anytime</small></div><div><span class="amb-step-num">03</span><strong>Represent</strong><small>Start after approval</small></div></div><div class="amb-member-entry"><div class="amb-member-mark">✦</div><div><strong>Returning ambassador?</strong><p>Access your status, tasks, resources, referrals and rewards.</p></div><button class="amb-member-button" onclick="amb('login')">SIGN IN →</button></div><div class="staff-gateway" aria-label="Staff sign-in choices"><div class="staff-entry"><h3>Host Portal</h3><p>Manage ambassadors, approve applications, and control manager accounts.</p><button class="btn aqua" onclick="amb('host')">HOST SIGN IN →</button></div><div class="staff-entry"><h3>Manager Portal</h3><p>Review ambassador activity and manage host access.</p><button class="btn yellow" onclick="amb('manager')">MANAGER SIGN IN →</button></div></div></section>`}
function loginForm(){return `<form class="form" onsubmit="signIn(event)"><label>Username or email<input name="username" required autocomplete="username" placeholder="yourusername or you@example.com"></label><label>PIN<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{4,6}" minlength="4" maxlength="6" required placeholder="Your PIN"></label><button type="submit" class="btn aqua">SIGN IN →</button></form>`}
function login(){return `<button class="back" onclick="amb('start')">← Ambassador home</button><div class="eyebrow">RETURNING APPLICANTS & AMBASSADORS</div><h1>Welcome <em>back</em></h1><div class="panel"><p class="sub">Sign in with the account you created when you applied. Pending applicants can sign in too.</p>${db.ambLoginError?`<div class="staff-message" role="alert">${E(db.ambLoginError)}</div>`:""}${loginForm()}<p class="muted">Forgot your PIN? Contact the team for help accessing your account.</p><div class="actions">${btn('NEW APPLICANT? APPLY',"amb('apply')",'ghost')}</div></div>`}
function signIn(e){e.preventDefault();let f=new FormData(e.target),u=String(f.get('username')).trim().toLowerCase(),pin=String(f.get('pin')).trim();let a=db.applications.find(x=>(x.username===u||x.email===u)&&x.demoPin===pin);db.ambLoginError='';if(!a){db.ambLoginError='Incorrect username/email or PIN. Please try again.';save();render();return}if(a.status==='disabled'){db.session=null;db.ambLoginError='Your ambassador account has been deactivated. You cannot sign in. Please contact the Skinz & Bubbles team.';save();amb('login');return}if(a.status==='rejected'){db.session=null;db.ambLoginError='Your ambassador application was not approved. Please contact the Skinz & Bubbles team if you need clarification.';save();amb('login');return}if(db.guestSession){const other=(db.guests||[]).find(g=>g.id===db.guestSession);if(other&&other.email!==a.email)db.guestSession=null;}a.loginCount=(Number(a.loginCount)||0)+1;a.lastLoginAt=new Date().toISOString();db.session=a.id;save();amb(a.status==='approved'?'dashboard':'status');flash(a.status==='approved'?'Welcome to your dashboard!':'Your application has not been approved yet. You can check its status here.')}

function dashboard(){let a=current();if(!a)return login();if(a.status==='pending')return statusPage();if(a.status==='approved'&&!a.username)return statusPage();if(a.status==='disabled')return `<h1>Account disabled</h1><div class="notice danger">Host has disabled this test account.</div>${btn('CHECK STATUS',"amb('status')",'ghost')}`;let approved=a.status==='approved';let done=a.tasks.length;let earned=points(a);let announced=(db.announcements||[]).filter(n=>!(a.readAnnouncements||[]).includes(n.id)).length;return `<div class="row" style="justify-content:space-between"><div><div class="eyebrow">AMBASSADOR HOME • 2027</div><h1>Hey, <em>${E(a.name.split(' ')[0])}!</em> 🫧</h1></div>${btn('SIGN OUT',"signOut()",'ghost small')}</div><div class="stats"><div class="stat"><strong>${done}/${tasks.length}</strong><span>TASKS DONE</span></div><div class="stat"><strong>${earned}</strong><span>POINTS</span></div><div class="stat"><strong>${announced}</strong><span>NEW NOTICES</span></div></div><div class="panel"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">Application</h2><p class="sub" style="margin:7px 0">${E(a.email)}</p></div><span class="status ${a.status}">${E(a.status.toUpperCase())}</span></div>${approved?'<div class="notice">Approved! You can now access tasks, content, a referral code, and announcements.</div>':'<div class="notice">Your application is being reviewed. Host Portal can approve it for testing.</div>'}</div>${approved?`<div class="panel"><div class="eyebrow">YOUR PERSONAL PROMO CODE</div><h2>${E(refCode(a))}</h2><p class="sub">Share your referral code with your crew. Referral rewards will be confirmed after ticketing is connected.</p><div class="actions">${btn('COPY MY CODE',`copyRef('${E(a.id)}')`,'aqua')}${btn('COPY INVITE',`copyInvite('${E(a.id)}')`,'ghost')}</div><p class="muted">Referral activity: ${a.referralCount||0} • Recorded by your host.</p></div><div class="panel"><h2>My tasks — ${done} of ${tasks.length}</h2><div class="progress"><b style="width:${done/tasks.length*100}%"></b></div><p class="sub">Tick each task, then submit an Instagram or TikTok link. Host can review and approve proof.</p>${tasks.map(([name,short],i)=>`<div class="task"><label><input type="checkbox" ${a.tasks.includes(i)?'checked':''} onchange="taskCheck(${i},this.checked)"><span>${E(name)}</span></label><p>${E(short)}</p><label class="mini-label">Instagram / TikTok proof link<input type="url" id="proof${i}" inputmode="url" placeholder="https://www.instagram.com/..." value="${E(a.proofs[i]||'')}"></label><div class="actions">${btn('SUBMIT LINK',`saveProof(${i})`,'small ghost')}<span class="proof-pill">${E(proofLabel(a,i))}</span></div></div>`).join('')}</div><div class="panel"><h2>Rewards & progress</h2><div class="reward-score">${earned} <span>POINTS</span></div><p class="sub">Earn 10 points per completed task, 20 per approved proof and 5 per recorded referral. Points shown here have no cash value.</p>${['Bubbles Starter — 20 pts','Team Promoter — 60 pts','Summer Ambassador — 120 pts'].map((x,i)=>`<p class="reward-row">${earned >= [20,60,120][i]?'🏆':'○'} ${x} <span>${earned >= [20,60,120][i]?'UNLOCKED':'LOCKED'}</span></p>`).join('')}</div><div class="panel"><h2>Host announcements ${announced?`<span class="new-dot">${announced} NEW</span>`:''}</h2>${announcementList(a)}</div><div class="panel"><h2>Download center</h2><p class="sub">Download approved graphics and videos, and copy captions in one tap.</p>${resourceCenter()}</div>`:''}<div class="actions">${btn('AMBASSADOR HOME',"amb('start')",'ghost')}</div>`}
function taskCheck(i,checked){let a=current();if(!a||a.status!=='approved')return;a.tasks=checked?[...new Set([...a.tasks,i])]:a.tasks.filter(x=>x!==i);save();render();flash(checked?'Task marked complete':'Task reopened')}
function saveProof(i){let a=current();if(!a||a.status!=='approved')return;let url=document.getElementById('proof'+i).value.trim();if(url){try{let u=new URL(url);if(u.protocol!=='https:'||!/(^|\.)(instagram\.com|tiktok\.com)$/.test(u.hostname)){flash('Enter a valid Instagram or TikTok post link');return}}catch{flash('Please enter a valid link');return}}a.proofs[i]=url.slice(0,500);a.proofStatus=a.proofStatus||{};a.proofStatus[i]=url?'submitted':'none';save();render();flash(url?'Proof submitted for host review':'Proof cleared') }
function signOut(){db.session=null;save();amb('start')}
const captions=["The summer is calling. 🫧 Skinz & Bubbles is taking over Kingston, Jamaica — July 31, 2027. Welcome to the Bubbles! #SkinzAndBubbles #Jamaica2027","Sunshine, music, water and the people who make every memory count. Join the Skinz & Bubbles experience in Kingston. 🫧 #WelcomeToTheBubbles #SkinzAndBubbles","Not just an event. A Jamaica summer lifestyle. See you July 31, 2027. 💗🫧 #SkinzAndBubbles #KingstonJamaica"];
function resourceCenter(){return `<div class="resource"><div><strong>Official teaser caption</strong><small>Copy a ready-to-post announcement</small></div>${btn('COPY',"copyCaption(0)",'small aqua')}</div><div class="resource"><div><strong>Summer lifestyle caption</strong><small>Sell the experience and your crew</small></div>${btn('COPY',"copyCaption(1)",'small aqua')}</div><div class="resource"><div><strong>Travel & Jamaica caption</strong><small>For overseas and local communities</small></div>${btn('COPY',"copyCaption(2)",'small aqua')}</div><div class="resource"><div><strong>Approved flyer — vertical</strong><small>1080 × 1920 branded PNG story</small></div>${btn('DOWNLOAD',"downloadPoster()",'small yellow')}</div><div class="resource"><div><strong>Approved flyer — square</strong><small>1080 × 1080 branded PNG feed post</small></div>${btn('DOWNLOAD',"downloadSquare()",'small yellow')}</div><div class="resource"><div><strong>Ambassador video teaser</strong><small>Short promotional video</small></div>${btn('DOWNLOAD',"downloadVideo()",'small yellow')}</div><div class="resource"><div><strong>Caption pack</strong><small>Text file with all three captions</small></div>${btn('DOWNLOAD',"downloadCaptions()",'small aqua')}</div><div class="resource"><div><strong>Approved hashtags</strong><small>#SkinzAndBubbles #WelcomeToTheBubbles #Jamaica2027</small></div>${btn('COPY',"copyHashtags()",'small aqua')}</div>`}
async function copyText(s){try{await navigator.clipboard.writeText(s);flash('Copied to clipboard')}catch{let t=document.createElement('textarea');t.value=s;document.body.append(t);t.select();try{document.execCommand('copy');flash('Copied')}catch{flash('Copy not supported; please select the text')};t.remove()}}
function copyCaption(i){copyText(captions[i])};function copyHashtags(){copyText('#SkinzAndBubbles #WelcomeToTheBubbles #Jamaica2027 #KingstonJamaica #SummerInJamaica')}
function downloadPoster(){const c=document.createElement('canvas');c.width=1080;c.height=1920;const x=c.getContext('2d');let im=new Image();im.onload=()=>{x.drawImage(im,0,0,1080,1920);let g=x.createLinearGradient(0,0,0,1920);g.addColorStop(0,'#04193f77');g.addColorStop(.6,'#051a3e22');g.addColorStop(1,'#041f4d');x.fillStyle=g;x.fillRect(0,0,1080,1920);x.textAlign='center';x.fillStyle='#ffe64a';x.font='bold 65px Arial';x.fillText('SKINZ & BUBBLES',540,210);x.font='bold 38px Arial';x.fillText('AMBASSADOR TEAM',540,285);x.fillStyle='white';x.font='bold 70px Arial';x.fillText('WELCOME TO',540,1555);x.fillText('THE BUBBLES',540,1640);x.font='bold 38px Arial';x.fillText('KINGSTON, JAMAICA • JULY 31, 2027',540,1740);const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='Skinz-and-Bubbles-Ambassador-Story.png';a.click();db.downloadCount++;save();flash('Ambassador poster downloaded')};im.onerror=()=>flash('Poster image unavailable');im.src=IMG.hero}

const STAFF_DEMO_HOST={id:'host-primary',name:'Primary Host',username:'hostdemo',pin:'246810',status:'active',role:'host'};
const STAFF_DEMO_MANAGER={id:'manager-primary',name:'Demo Manager',username:'managerdemo',pin:'135790',status:'active',role:'manager'};
function ensureStaff(){db.staffUsers=db.staffUsers||[STAFF_DEMO_HOST,STAFF_DEMO_MANAGER].map(x=>({...x}));db.staffSession=db.staffSession||null;db.staffLoginError=db.staffLoginError||'';db.ambLoginError=db.ambLoginError||''}
ensureStaff();
function staffCurrent(){ensureStaff();let u=db.staffUsers.find(a=>a.id===db.staffSession);return u&&u.status==='active'?u:null}
function roleOK(role){let u=staffCurrent();return !!u&&(!role||u.role===role)}
function staffSignIn(event,role){event.preventDefault();ensureStaff();let f=new FormData(event.target),user=String(f.get('username')||'').trim().toLowerCase(),pin=String(f.get('pin')||'');let a=db.staffUsers.find(x=>x.role===role&&x.username===user&&x.pin===pin);if(!a){db.staffLoginError='Incorrect username or PIN. Please try again.';db.staffSession=null;save();render();return}if(a.status!=='active'){db.staffLoginError='Your '+role+' account has been deactivated. Please contact an authorized administrator.';db.staffSession=null;save();render();return}db.staffLoginError='';db.staffSession=a.id;db.ambView=role;save();render();flash('Signed in to '+(role==='host'?'Host':'Manager')+' Portal')}
function staffSignOut(){db.staffSession=null;db.staffLoginError='';save();amb('start')}
function staffLogin(role){let name=role==='host'?'Host':'Manager';return `<button class="back" onclick="amb('start')">← Ambassador Hub</button><div class="eyebrow">STAFF ACCESS</div><h1>${name} <em>Sign In</em></h1><div class="staff-banner"><strong>Separate ${name} account</strong><p>Ambassadors cannot access staff dashboards. Staff accounts are role-specific.</p></div>${db.staffLoginError?`<div class="staff-message" role="alert">${E(db.staffLoginError)}</div>`:''}<div class="staff-panel staff-login"><form class="form" onsubmit="staffSignIn(event,'${role}')"><label>${name} username<input name="username" autocomplete="username" required placeholder="${role==='host'?'hostdemo':'managerdemo'}"></label><label>Staff PIN<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required placeholder="6-digit PIN"></label><button class="btn aqua" type="submit">SIGN IN TO ${name.toUpperCase()} PORTAL</button></form><div class="notice">Preview staff access: <strong>${role==='host'?'hostdemo / 246810':'managerdemo / 135790'}</strong>. These access codes are for this preview only.</div></div>`}
function staffHeader(role){let a=staffCurrent();return `<div class="staff-banner"><div class="staff-who"><div><strong>${role==='host'?'Host Control Center':'Manager Control Center'}</strong><small>Signed in as ${E(a.name)} • ${E(a.username)}</small></div><button class="btn small yellow" onclick="staffSignOut()">SIGN OUT</button></div><p>${role==='host'?'Control ambassadors, review content and manage manager accounts.':'Review ambassadors and suspend or restore Host access.'}</p></div>`}
function staffChangePin(e){e.preventDefault();let a=staffCurrent();if(!a)return;let f=new FormData(e.target),old=String(f.get('old')||''),fresh=String(f.get('fresh')||''),confirmPin=String(f.get('confirm')||'');if(old!==a.pin||!/^[0-9]{6}$/.test(fresh)||fresh!==confirmPin){flash('Check your old PIN and the two matching new six-digit PINs.');return}a.pin=fresh;save();render();flash('Staff PIN changed')}
function staffPinPanel(){return `<details class="staff-panel"><summary><strong>Change my staff PIN</strong></summary><form class="form" onsubmit="staffChangePin(event)"><label>Current PIN<input name="old" type="password" inputmode="numeric" minlength="6" maxlength="6" required></label><label>New PIN<input name="fresh" type="password" inputmode="numeric" minlength="6" maxlength="6" required></label><label>Confirm new PIN<input name="confirm" type="password" inputmode="numeric" minlength="6" maxlength="6" required></label><button class="btn aqua" type="submit">CHANGE PIN</button></form></details>`}
function manageStaffStatus(id,status){let me=staffCurrent();if(!me)return;let target=db.staffUsers.find(x=>x.id===id);if(!target||target.id===me.id){flash('You cannot change your own staff access.');return}if(me.role==='host'&&target.role!=='manager'||me.role==='manager'&&target.role!=='host'){flash('This action is not permitted for your role.');return}if(me.role==='manager'&&target.role==='host'&&status==='disabled'){let active=db.staffUsers.filter(x=>x.role==='manager'&&x.status==='active');if(!active.length){flash('At least one active manager is required.');return}}target.status=status;save();render();flash(target.name+' is now '+(status==='active'?'active':'deactivated'))}
function resetStaffPin(id){let me=staffCurrent(),target=db.staffUsers.find(x=>x.id===id);if(!me||!target||me.id===target.id)return flash('Use Change my PIN for your own account.');if(me.role==='host'&&target.role!=='manager'||me.role==='manager'&&target.role!=='host')return flash('You cannot reset this account.');let fresh=prompt('Enter a new six-digit PIN for '+target.name+':');if(fresh===null)return;if(!/^[0-9]{6}$/.test(fresh))return flash('PIN must have six digits.');target.pin=fresh;save();render();flash('Staff PIN reset')}
function removeManager(id){if(!roleOK('host'))return flash('Host sign-in required');let target=db.staffUsers.find(x=>x.id===id&&x.role==='manager');if(!target||!confirm('Delete demo manager '+target.name+'?'))return;db.staffUsers=db.staffUsers.filter(x=>x.id!==id);save();render();flash('Demo manager account removed')}
function createManager(e){e.preventDefault();if(!roleOK('host')){flash('Only an active Host can create managers.');return}let f=new FormData(e.target),name=String(f.get('name')||'').trim(),username=String(f.get('username')||'').trim().toLowerCase(),pin=String(f.get('pin')||'');if(!name||!/^[a-z0-9_]{3,25}$/.test(username)||!/^[0-9]{6}$/.test(pin)){flash('Enter a name, valid username, and six-digit PIN.');return}if(db.staffUsers.some(x=>x.username===username)||db.applications.some(x=>x.username===username)){flash('Username already exists.');return}db.staffUsers.push({id:'mgr-'+Date.now(),name,username,pin,role:'manager',status:'active'});save();render();flash('Manager account created')}
function managerList(){if(!roleOK('host'))return '';return `<div class="staff-panel"><h2>Manager Accounts</h2><p>Host can activate or deactivate managers and create new manager logins.</p><div class="staff-table"><table><thead><tr><th>Name</th><th>Username</th><th>Status</th><th>Controls</th></tr></thead><tbody>${db.staffUsers.filter(x=>x.role==='manager').map(x=>`<tr><td>${E(x.name)}</td><td>${E(x.username)}</td><td><span class="staff-status ${x.status==='active'?'':'off'}">${E(x.status)}</span></td><td>${x.status==='active'?btn('DEACTIVATE',`manageStaffStatus('${x.id}','disabled')`,'small ghost'):btn('RESTORE',`manageStaffStatus('${x.id}','active')`,'small aqua')}${btn('RESET PIN',`resetStaffPin('${x.id}')`,'small yellow')}${x.id==='manager-primary'?'':btn('DELETE',`removeManager('${x.id}')`,'small ghost')}</td></tr>`).join('')}</tbody></table></div><details><summary><strong>+ Add manager account</strong></summary><form class="form" onsubmit="createManager(event)"><label>Manager full name<input name="name" required maxlength="70"></label><label>Unique username<input name="username" required minlength="3" maxlength="25" pattern="[a-zA-Z0-9_]{3,25}"></label><label>Temporary six-digit demo PIN<input name="pin" required pattern="[0-9]{6}" type="password" inputmode="numeric" maxlength="6"></label><button class="btn aqua" type="submit">CREATE MANAGER</button></form></details></div>`}
function hostControlsForManager(){if(!roleOK('manager'))return '';return `<div class="staff-panel"><h2>Host Access Oversight</h2><p>Managers can suspend or restore Host access. Suspended hosts cannot open the Host Control Center or manage managers.</p><div class="staff-table"><table><thead><tr><th>Host</th><th>Username</th><th>Status</th><th>Control</th></tr></thead><tbody>${db.staffUsers.filter(x=>x.role==='host').map(x=>`<tr><td>${E(x.name)}</td><td>${E(x.username)}</td><td><span class="staff-status ${x.status==='active'?'':'off'}">${E(x.status)}</span></td><td>${x.status==='active'?btn('SUSPEND HOST',`manageStaffStatus('${x.id}','disabled')`,'small ghost'):btn('RESTORE HOST',`manageStaffStatus('${x.id}','active')`,'small aqua')}${btn('RESET HOST PIN',`resetStaffPin('${x.id}')`,'small yellow')}</td></tr>`).join('')}</tbody></table></div></div>`}
function manager(){return roleOK('manager')?staffHeader('manager')+hostControlsForManager()+staffPinPanel()+hostDashboard('manager'):staffLogin('manager')}

function hostDashboard(role){let applications=db.applications||[];let pending=applications.filter(a=>a.status==='pending').length;let approved=applications.filter(a=>a.status==='approved').length;let proofs=applications.reduce((n,a)=>n+Object.values(a.proofStatus||{}).filter(v=>v==='submitted').length,0);return `<div class="eyebrow">AMBASSADOR MANAGEMENT • DEMO</div><h1>Ambassador <em>Operations</em></h1><div class="notice">Local demonstration only. Staff permissions must be enforced on a secure server before real use.</div><div class="stats"><div class="stat"><strong>${applications.length}</strong><span>APPLICATIONS</span></div><div class="stat"><strong>${pending}</strong><span>PENDING</span></div><div class="stat"><strong>${approved}</strong><span>APPROVED</span></div><div class="stat"><strong>${proofs}</strong><span>PROOF TO REVIEW</span></div><div class="stat"><strong>${applications.reduce((sum,a)=>sum+(Number(a.loginCount)||0),0)}</strong><span>TOTAL AMBASSADOR SIGN-INS</span></div></div><div class="panel"><div class="row" style="justify-content:space-between"><h2>Applications</h2>${btn('ADD SAMPLE',"seedAmbassador()",'small aqua')}</div><div class="tablewrap"><table class="table"><thead><tr><th>AMBASSADOR</th><th>CONTACT</th><th>STATUS</th><th>PROGRESS</th><th>LOGIN ACTIVITY</th><th>ACTIONS</th></tr></thead><tbody>${applications.length?applications.map(a=>`<tr><td><strong>${E(a.name)}</strong><br><span class="muted">${E(a.instagram)}</span></td><td>${E(a.email)}<br><span class="muted">${E(a.phone)}</span></td><td><span class="status ${a.status}">${E(a.status)}</span></td><td>${a.tasks.length}/${tasks.length} tasks<br>${points(a)} points<br>${a.referralCount||0} referrals</td><td><strong>${Number(a.loginCount)||0}</strong> successful sign-ins<br><span class="muted">${a.lastLoginAt?E(new Date(a.lastLoginAt).toLocaleString()):'Never signed in'}</span></td><td><div class="actions">${a.status!=='approved'?btn('APPROVE',`setStatus('${a.id}','approved')`,'small aqua'):''}${a.status==='disabled'?btn('RESTORE TO PENDING',`setStatus('${a.id}','pending')`,'small yellow'):''}${a.status!=='disabled'?btn('DISABLE',`setStatus('${a.id}','disabled')`,'small ghost'):''}${btn('VIEW PROOF',`details('${a.id}')`,'small yellow')}${role==='host'?btn('RESET PIN',`openNamedReset('${a.id}')`,'small ghost'):''}${a.status==='approved'?btn('+ DEMO REFERRAL',`addReferral('${a.id}')`,'small ghost'):''}${role==='host'?btn('DELETE',`removeAmbassador('${a.id}')`,'small ghost'):''}</div></td></tr>`).join(''):'<tr><td colspan="6">No applications yet.</td></tr>'}</tbody></table></div></div>${role==='host'?`<div class="panel"><div class="eyebrow">HOST • ACCOUNT HELP</div><h2>Reset ambassador PIN</h2><p class="sub">Enter the ambassador’s full name to find their application. Choose the correct match, then type the name again to authorize the reset. No PIN will change until you confirm.</p><form class="form" onsubmit="findAmbassadorForReset(event)"><label>Ambassador full name<input name="ambassadorName" autocomplete="off" maxlength="120" required placeholder="Enter full name"></label><button class="btn aqua" type="submit">FIND AMBASSADOR →</button></form><div id="resetSearchResults" aria-live="polite"></div></div>`:''}<div class="panel"><h2>Post a host announcement</h2><p class="sub">Appears immediately in ambassadors’ dashboards in this browser.</p><form class="form" onsubmit="postAnnouncement(event)"><label>Announcement title<input name="title" maxlength="75" required placeholder="New promo materials are ready"></label><label>Message<textarea name="body" maxlength="600" required placeholder="Tell ambassadors what to do next"></textarea></label><button class="btn aqua" type="submit">PUBLISH ANNOUNCEMENT</button></form><div class="notice">${(db.announcements||[]).length} announcement(s) available.</div></div><div class="actions">${btn('OPEN APPLICATION',"amb('apply')",'yellow')}${role==='host'?btn('CLEAR PREVIEW DATA',"resetDemo()",'ghost'):''}</div>`}
function host(){return roleOK('host')?staffHeader('host')+managerList()+staffPinPanel()+hostDashboard('host'):staffLogin('host')}
function setStatus(id,status){if(!staffCurrent())return flash('Staff sign-in required');let a=db.applications.find(x=>x.id===id);if(!a)return;a.status=status;save();render();flash(a.name+' → '+status)}
function findAmbassadorForReset(e){
 e.preventDefault();if(!roleOK('host'))return flash('Host sign-in required');
 const form=new FormData(e.target),name=String(form.get('ambassadorName')||'').trim();
 const results=document.getElementById('resetSearchResults');if(!results)return;
 if(name.length<2){results.innerHTML='<div class="notice danger">Enter the ambassador full name.</div>';return}
 const hits=db.applications.filter(a=>a.name.trim().toLocaleLowerCase()===name.toLocaleLowerCase());
 if(!hits.length){results.innerHTML='<div class="notice danger">No exact match. Check the ambassador’s full name in Applications and try again.</div>';return}
 results.innerHTML='<div class="notice">'+hits.length+' matching application(s). Select by name and email:</div>'+hits.map(a=>`<div class="row" style="justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #bce8ee"><span><strong>${E(a.name)}</strong><br><small>${E(a.email)} • ${E(a.status)}</small></span>${btn('SELECT AMBASSADOR',`openNamedReset('${a.id}')`,'small aqua')}</div>`).join('');
}
function openNamedReset(id){
 if(!roleOK('host'))return flash('Host sign-in required');const a=db.applications.find(x=>x.id===id);if(!a)return flash('Ambassador not found');
 document.getElementById('accessModal')?.remove();
 let overlay=document.createElement('div');overlay.className='access-modal';overlay.id='accessModal';
 overlay.innerHTML=`<div class="panel access-panel" role="dialog" aria-modal="true" aria-label="Confirm ambassador reset"><h2>Reset ambassador PIN</h2><p>You selected <strong>${E(a.name)}</strong> (${E(a.email)}).</p><p class="sub">To prevent resetting the wrong account, type the ambassador’s <strong>full name</strong> exactly as shown.</p><form class="form" onsubmit="confirmAmbassadorPinReset(event,'${a.id}')"><label>Confirm ambassador full name<input name="confirmName" required autocomplete="off" maxlength="120" placeholder="${E(a.name)}"></label><button class="btn aqua" type="submit">CONFIRM & RESET PIN</button><button class="btn ghost" type="button" onclick="document.getElementById('accessModal').remove()">CANCEL</button></form><div class="notice danger">For live accounts, resets will use verified identity and secure recovery links.</div></div>`;
 document.body.append(overlay);
}
function confirmAmbassadorPinReset(e,id){
 e.preventDefault();if(!roleOK('host'))return flash('Host sign-in required');
 const a=db.applications.find(x=>x.id===id);if(!a)return flash('Ambassador no longer exists');
 const entered=String(new FormData(e.target).get('confirmName')||'').trim();
 if(entered!==a.name.trim()){flash('The full name does not match. No changes were made.');return}
 if(!confirm('Reset the PIN for '+a.name+' ('+a.email+')?'))return;
 let stem=(a.email.split('@')[0]||'ambassador').replace(/[^a-z0-9_]/gi,'').toLowerCase().slice(0,14);
 if(stem.length<3)stem='ambassador';
 if(!a.username){let candidate=stem,n=1;while(db.applications.some(x=>x.id!==a.id&&x.username===candidate))candidate=stem+ ++n;a.username=candidate}
 a.demoPin=String(Math.floor(100000+Math.random()*900000));a.lastPinResetAt=new Date().toISOString();save();document.getElementById('accessModal')?.remove();render();
 const overlay=document.createElement('div');overlay.className='access-modal';overlay.id='accessModal';
 overlay.innerHTML=`<div class="panel access-panel" role="dialog" aria-modal="true" aria-label="Test PIN reset completed"><h2>PIN reset for ${E(a.name)}</h2><p>Temporary sign-in details:</p><p class="reset-credential">Username: <strong>${E(a.username)}</strong></p><p class="reset-credential">Temporary PIN: <strong>${E(a.demoPin)}</strong></p><p class="muted">This reset does not change the ambassador’s approval status or sign-in count.</p><div class="notice danger">Before launch, account recovery will use secure identity checks.</div><button class="btn yellow" onclick="document.getElementById('accessModal').remove()">CLOSE</button></div>`;
 document.body.append(overlay);
}
function resetAccess(id){return openNamedReset(id)}
function removeAmbassador(id){if(!roleOK('host'))return flash('Host sign-in required');let a=db.applications.find(x=>x.id===id);if(!a||!confirm('Delete the application for '+a.name+'?'))return;db.applications=db.applications.filter(x=>x.id!==id);if(db.session===id)db.session=null;save();render();flash('Application deleted')}
function seedAmbassador(){if(!staffCurrent())return flash('Staff sign-in required');let email='sample'+Date.now().toString().slice(-5)+'@example.test';db.applications.push({id:'SB'+Date.now(),name:'Kayla (Example)',email,phone:'555-0100',instagram:'@sampleambassador',tiktok:'@sampleambassador',why:'I love Jamaican summer experiences.',status:'pending',tasks:[],proofs:{},date:new Date().toLocaleDateString()});save();render();flash('Example application added')}
function details(id){if(!staffCurrent())return flash('Staff sign-in required');let a=db.applications.find(x=>x.id===id);if(!a)return;let el=document.getElementById('details');if(!el){el=document.createElement('div');el.id='details';app.append(el)}el.innerHTML=`<div class="panel" style="border:2px solid var(--yellow)"><button class="back" onclick="document.getElementById('details').remove()">← Close details</button><h2>${E(a.name)} — Host Review</h2><p class="sub">${E(a.email)} • ${E(a.instagram)} • ${E(a.tiktok||'No TikTok')}<br><strong>Status:</strong> ${E(a.status)} • <strong>Promo code:</strong> ${E(refCode(a))} • <strong>Points:</strong> ${points(a)}</p><p class="sub"><strong>Successful sign-ins:</strong> ${Number(a.loginCount)||0}<br><strong>Last sign-in:</strong> ${a.lastLoginAt?E(new Date(a.lastLoginAt).toLocaleString()):'Never'}</p><h3>Task proof submissions</h3>${tasks.map(([name],i)=>`<div class="review"><strong>${a.tasks.includes(i)?'✅':'⬜'} ${E(name)}</strong><p>${a.proofs[i]?`<a target="_blank" rel="noopener noreferrer" href="${E(a.proofs[i])}">${E(a.proofs[i])}</a>`:'No link submitted'}</p><p class="muted">${E(proofLabel(a,i))}</p>${a.proofs[i]?`<div class="actions">${btn('APPROVE PROOF',`reviewProof('${a.id}',${i},'approved')`,'small aqua')}${btn('REJECT PROOF',`reviewProof('${a.id}',${i},'rejected')`,'small ghost')}</div>`:''}</div>`).join('')}</div>`;el.scrollIntoView({behavior:'smooth',block:'start'})}
function resetDemo(){if(!roleOK('host'))return flash('Host sign-in required');if(!confirm('Clear all applications, tasks and saved selections on this device?'))return;let staff=db.staffUsers, staffSession=db.staffSession;db={...initial,staffUsers:staff,staffSession,view:'Ambassadors',ambView:'host'};save();render();flash('Preview records cleared')}
function ambassadors(){let sub=db.ambView;return sub==='apply'?application():sub==='status'?statusPage():sub==='setup'?setupLoginPage(current()):sub==='login'?login():sub==='dashboard'?dashboard():sub==='host'?host():sub==='manager'?manager():ambassadorHome()}
function render(){const tabs=[['Home','⌂'],['Experience','✦'],['Jamaica','☀'],['Lineup','♫'],['Tickets','🎟'],['Ambassadors','★']];document.getElementById('nav').innerHTML=tabs.map(([t,ic])=>`<button class="tab ${db.view===t?'on':''}" onclick="navigate('${t}')" aria-label="${t}" ${db.view===t?'aria-current="page"':''}><strong>${ic}</strong>${t==='Ambassadors'?'Team':t}</button>`).join('');app.innerHTML= db.view==='Home'?home():db.view==='Experience'?experience():db.view==='Jamaica'?jamaica():db.view==='Lineup'?lineup():db.view==='Tickets'?tickets():ambassadors();app.insertAdjacentHTML('beforeend','<p class="footer">SKINZ & BUBBLES • PREVIEW • NO LIVE TICKET SALES</p>')}

const VIDEO_DATA = 'data:video/mp4;base64,';
function statusPage(){let a=current();if(!a)return `<button class="back" onclick="amb('start')">← Ambassador home</button><div class="eyebrow">APPLICATION STATUS</div><h1>Check your <em>status</em></h1><div class="panel"><p class="sub">Sign in using the username/email and PIN you created when applying.</p>${loginForm()}<p class="muted">Email alone cannot reveal your application.</p></div><div class="panel"><h3>Applied before the PIN feature?</h3><p class="sub">Contact the host to reset your account PIN. They can find your application by your full name.</p><p class="muted">Ask the event team to reset your access. Staff-only features require separate sign-in.</p></div>`;return `<button class="back" onclick="amb('start')">← Ambassador home</button><div class="eyebrow">MY APPLICATION STATUS</div><h1>Hi, <em>${E(a.name.split(' ')[0])}</em></h1><div class="panel"><div class="row" style="justify-content:space-between"><h2>Application</h2><span class="status ${E(a.status)}">${E(a.status.toUpperCase())}</span></div><p class="sub">${E(a.email)} • Submitted ${E(a.date||'recently')}</p><div class="notice">${a.status==='pending'?'Your application is being reviewed. Use this same login when you return.':a.status==='approved'?'Congratulations! Your application was approved. Your ambassador dashboard is ready.':'Contact the host about your application.'}</div>${a.status==='approved'?btn('OPEN AMBASSADOR DASHBOARD →',"amb('dashboard')",'yellow'):''}<div class="actions">${btn('SIGN OUT',"signOut()",'ghost small')}${btn('CHECK FOR UPDATES',"render()",'aqua small')}</div></div>`}
function lookupStatus(e){return signIn(e)}

function setupLoginPage(a){return statusPage()}
function createLogin(e){return signIn(e)}

function refCode(a){return 'SB-'+a.id.slice(-5).toUpperCase()}
function copyRef(id){let a=db.applications.find(x=>x.id===id);if(a)copyText(refCode(a))}
function copyInvite(id){let a=db.applications.find(x=>x.id===id);if(a)copyText('Join us at Skinz & Bubbles 2027 in Kingston, Jamaica on July 31! My ambassador referral code is '+refCode(a)+' (ticket tracking begins once sales open).')}
function proofLabel(a,i){return ({submitted:'WAITING FOR REVIEW',approved:'✓ APPROVED',rejected:'NEEDS NEW LINK',none:'NOT SUBMITTED'})[(a.proofStatus||{})[i]||'none']}
function points(a){return a.tasks.length*10+Object.values(a.proofStatus||{}).filter(v=>v==='approved').length*20+(a.referralCount||0)*5}
function reviewProof(id,i,state){if(!staffCurrent())return flash('Staff sign-in required');let a=db.applications.find(x=>x.id===id);if(!a||!a.proofs[i])return;a.proofStatus=a.proofStatus||{};a.proofStatus[i]=state;save();render();details(id);flash('Proof '+state)}
function addReferral(id){if(!staffCurrent())return flash('Staff sign-in required');let a=db.applications.find(x=>x.id===id);if(!a)return;a.referralCount=(a.referralCount||0)+1;save();render();flash('Referral recorded. Ticket sales are not linked yet.')}
function postAnnouncement(e){e.preventDefault();if(!staffCurrent())return flash('Staff sign-in required');let f=new FormData(e.target), title=String(f.get('title')).trim(),body=String(f.get('body')).trim();if(!title||!body)return;db.announcements.unshift({id:'ANN'+Date.now(),title:title.slice(0,75),body:body.slice(0,600),date:new Date().toLocaleString()});save();render();flash('Announcement published')}
function announcementList(a){return db.announcements?.length?db.announcements.map(n=>`<div class="announce"><div class="row" style="justify-content:space-between"><strong>${E(n.title)}</strong>${(a.readAnnouncements||[]).includes(n.id)?'<span class="muted">READ</span>':'<span class="new-dot">NEW</span>'}</div><p class="sub">${E(n.body)}</p><small class="muted">${E(n.date)}</small><div class="actions">${btn((a.readAnnouncements||[]).includes(n.id)?'MARK UNREAD':'MARK READ',`toggleAnnouncement('${n.id}')`,'small ghost')}</div></div>`).join(''):'<p class="sub">No announcements yet.</p>'}
function toggleAnnouncement(id){let a=current();if(!a)return;a.readAnnouncements=a.readAnnouncements||[];a.readAnnouncements=a.readAnnouncements.includes(id)?a.readAnnouncements.filter(v=>v!==id):[...a.readAnnouncements,id];save();render()}
function downloadBlob(bytes,name,type){const a=document.createElement('a'),blob=new Blob([bytes],{type});a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);flash(name+' downloaded')}
function downloadCaptions(){downloadBlob(captions.map((s,i)=>'CAPTION '+(i+1)+'\n'+s).join('\n\n')+'\n\nHASHTAGS\n#SkinzAndBubbles #WelcomeToTheBubbles #Jamaica2027','Skinz-Bubbles-2027-Ambassador-Captions.txt','text/plain')}
function downloadVideo(){let a=document.createElement('a');a.href=VIDEO_DATA;a.download='Skinz-Bubbles-2027-Ambassador-Teaser.mp4';document.body.append(a);a.click();a.remove();flash('Sample MP4 teaser downloaded')}
function downloadSquare(){const c=document.createElement('canvas');c.width=c.height=1080;const x=c.getContext('2d');let im=new Image();im.onload=()=>{x.drawImage(im,0,0,1080,1080);x.fillStyle='#052443cc';x.fillRect(0,0,1080,1080);x.textAlign='center';x.fillStyle='#ff1a91';x.font='bold 66px Arial';x.fillText('SKINZ & BUBBLES',540,390);x.fillStyle='#ffe64a';x.font='bold 50px Arial';x.fillText('JOIN THE AMBASSADOR TEAM',540,510);x.fillStyle='white';x.font='bold 39px Arial';x.fillText('KINGSTON, JAMAICA',540,660);x.fillText('JULY 31, 2027',540,718);c.toBlob(b=>{downloadBlob(b,'Skinz-Bubbles-2027-Ambassador-Square.png','image/png')},'image/png')};im.src=IMG.hero}


// V4 visual redesign: the existing Ambassador Hub logic and saved browser data remain unchanged.
const originalNavigate = navigate;
let lineupFilter='All';
const freeButtons=(arr)=>arr.map(x=>`<button class="more-option" onclick="${x[2]}"><span>${x[0]}</span><span>${x[1]}</span><span>→</span></button>`).join('');
function morePage(){return `<div class="eyebrow">YOUR SKINZ & BUBBLES WORLD</div><h1 class="headline">Explore <span class="white">More</span></h1><p class="sub">Everything you need for your summer in Jamaica.</p>${freeButtons([['♫','Music & Lineup',"navigate('Lineup')"],['★','Ambassador Hub',"amb('start')"],['✓','My saved moments',"navigate('My Bubbles')"],['✦','Event Guide & Safety',"navigate('Event Guide')"]])}<div class="panel"><h2>Be part of the Bubbles 🫧</h2><p class="sub">Ambassadors can apply, log in after approval, download content, track tasks, submit proof and rewards. Hosts can approve and announce.</p>${btn('OPEN AMBASSADOR HUB →',"amb('start')",'yellow')}</div>`}
function myBubbles(){return `<button class="back" onclick="navigate('More')">← More</button><h1>My <em>Bubbles</em></h1><div class="panel"><h2>Your saved experiences</h2>${db.favorites.length?db.favorites.map(x=>`<div class="resource"><strong>${E(x)}</strong><button class="btn small ghost" onclick="toggleFavorite(${E(JSON.stringify(x))})">REMOVE</button></div>`).join(''):'<p class="sub">Save a moment from the Experience or Lineup screen to see it here.</p>'}</div>${db.ticket?`<div class="panel"><h3>Your ticket preference</h3><p>${E(db.ticket)} • saved selection, not a paid ticket</p>${btn('VIEW TICKETS',"navigate('Tickets')")}</div>`:''}`}
function eventGuide(){return `<button class="back" onclick="navigate('More')">← More</button><h1>Event <em>Guide</em></h1><div class="panel"><h2>Kingston, Jamaica • July 31, 2027</h2><p class="sub">The official site map, entrances, emergency contacts, medical stations and transport guidance will appear once confirmed.</p><div class="notice">Please do not rely on this prototype for emergency guidance or venue directions.</div></div>`}
home=function(){return `<div class="glam-hero home-lead" style="background-image:url('${IMG.hero}')"></div><div class="hero-after"><div class="hero-date">📍 KINGSTON, JAMAICA &nbsp; • &nbsp; JULY 31, 2027</div><button class="btn" onclick="navigate('Tickets')">🎟 GET TICKETS &nbsp; →</button></div><div class="stats"><div class="stat"><strong>${countdown()}</strong><span>DAYS TO GO</span></div><div class="stat"><strong>31</strong><span>JULY 2027</span></div><div class="stat"><strong>JA</strong><span>KINGSTON</span></div></div><div class="section"><div class="eyebrow">MORE THAN A PARTY. IT'S A LIFESTYLE.</div><h2>Welcome to your summer.</h2><p class="sub">The sunshine, the music, the people, the unforgettable Jamaica energy.</p><div class="actions">${btn('FEEL THE EXPERIENCE →',"navigate('Experience')",'aqua')}${btn('DISCOVER JAMAICA →',"navigate('Jamaica')",'yellow')}</div></div><div class="panel"><h2>Join the crew</h2><p class="sub">Apply to join the team, share the experience, and track your activity.</p>${btn('OPEN AMBASSADOR HUB →',"amb('start')")}</div>`};
experience=function(){let i=db.journey;return `<h1 class="headline center"><span class="white">The</span> Experience</h1><div class="kicker">MORE THAN A PARTY<br>IT'S A LIFESTYLE</div>${[['FOAM BLAST','Jamaica’s wildest foam experience','foam',2],['WATER RUSH','High-energy water action','water',2],['VIP & CABANAS','Elevated comfort & private space','cabana',3],['MUSIC & VIBES','Top DJs, energy, nonstop fun','dj',1]].map(([name,txt,img,step])=>`<button class="glossy-row" onclick="setMoment(${step})"><span class="thumb" style="background-image:url('${IMG[img]}')"></span><span class="grow"><b>${name}</b><small>${txt}</small></span><span class="bubble-arrow">→</span></button>`).join('')}<div class="panel"><div class="eyebrow">YOUR DAY • MOMENT ${i+1} OF ${steps.length}</div><h2>${steps[i][0]}</h2><p class="sub">${steps[i][1]}</p><div class="progress"><b style="width:${(i+1)*20}%"></b></div><div class="actions">${btn(db.favorites.includes(steps[i][0])?'♥ SAVED':'♡ SAVE THIS MOMENT',`toggleFavorite(${JSON.stringify(steps[i][0])})`,'ghost small')}${btn(i<4?'NEXT MOMENT →':'GET TICKETS →',i<4?'nextMoment()':"navigate('Tickets')",'aqua small')}${i?btn('← PREVIOUS','prevMoment()','ghost small'):''}</div></div>`};
jamaica=function(){let sel=db.guide;return `<h1 class="headline center"><span class="white">Discover</span> Jamaica</h1><p class="kicker">THE CULTURE • THE PEOPLE<br>THE FOOD • THE VIBES</p><div class="guide-hero" style="background-image:url('${IMG.jamaica}')"></div><div class="guide-grid">${[['activities','🌴','THINGS TO DO'],['food','🍴','JAMAICAN FOOD'],['stay','🧳','STAY'],['travel','✈','TRAVEL GUIDE']].map(([id,ic,label])=>`<button class="guide-tile" onclick="openGuide('${id}')"><span class="tile-icon">${ic}</span><span>${label}</span></button>`).join('')}</div><div style="text-align:center;font-size:48px;margin-top:5px">🇯🇲</div>${sel?`<div class="panel"><button class="back" onclick="openGuide('')">← Close guide</button><h2>${{activities:'Things to do',food:'Jamaican food',stay:'Hotels and stays',travel:'Travel guide'}[sel]}</h2>${guides[sel].map(([a,b])=>`<div class="guidecard"><h3>${a}</h3><p>${b}</p></div>`).join('')}<p class="muted">Hotel, restaurant and travel partner details will be confirmed before the event.</p></div>`:''}`};
lineup=function(){return `<h1 class="headline center"><span class="white">Music &</span> Lineup</h1><div class="guide-hero" style="height:300px;background-image:url('${IMG.dj}')"></div><div class="lineup-filters">${['All','DJs','Artists','Hosts'].map(n=>`<button class="${lineupFilter===n?'active':''}" onclick="lineupFilter='${n}';render()">${n}</button>`).join('')}</div><div class="music-alert"><div class="eyebrow">${lineupFilter.toUpperCase()} • COMING SOON</div><h2>Official announcements are on the way</h2><p class="sub">We'll show confirmed ${lineupFilter==='All'?'DJs, artists and hosts':lineupFilter.toLowerCase()} here. Names and set times in the reference image were concept placeholders.</p><div class="actions">${btn(db.favorites.includes('Lineup updates')?'♥ INTEREST SAVED':'♡ SAVE LINEUP UPDATES',"toggleFavorite('Lineup updates')",'aqua')}${btn('EXPLORE THE MUSIC →',"setMoment(1);navigate('Experience')",'ghost')}</div></div>`};
tickets=function(){return `<h1 class="headline center"><span class="white">Get</span> Tickets</h1><p class="kicker">CHOOSE YOUR<br>SKINZ & BUBBLES EXPERIENCE</p>${[['GENERAL ADMISSION','Full festival access','🎟',''],['VIP EXPERIENCE','Elevated access, exclusive perks','♛','pink'],['GROUP DEALS','Bring your crew & save','♧','yellow'],['CABANAS','Your private premium space','⌂','']].map(([name,d,icon,cl])=>`<button class="ticket-row ${cl} ${db.ticket===name?'selected':''}" onclick="selectTicket('${name}')"><span class="ticket-icon">${icon}</span><span class="grow"><b>${name} ${db.ticket===name?'✓':''}</b><small>${d}</small></span><span class="go">→</span></button>`).join('')}${db.ticket?`<div class="panel"><div class="eyebrow">YOUR TICKET SELECTION</div><h2>${E(db.ticket)}</h2><p class="sub">Your selection is saved in this browser. No real payment or ticket is issued.</p><div class="actions">${btn('CONTINUE TO CHECKOUT →','testCheckout()','yellow')}${btn('CHANGE SELECTION',"clearTicket()",'ghost')}</div></div>`:''}<div class="guide-hero" style="background-image:url('${IMG.cabana}');height:230px;margin:15px 0"></div><div class="demo-label">SAVED SELECTION • NOT VALID FOR ENTRY</div>`};
render=function(){const tabs=[['Home','⌂'],['Experience','✦'],['Jamaica','♧'],['Tickets','🎟'],['More','▦']];document.getElementById('nav').innerHTML=tabs.map(([t,ic])=>`<button class="tab ${(db.view===t||(t==='More'&&['Ambassadors','Lineup','My Bubbles','Event Guide'].includes(db.view)))?'on':''}" onclick="navigate('${t}')" aria-label="${t}" ${db.view===t?'aria-current="page"':''}><strong>${ic}</strong>${t}</button>`).join('');app.innerHTML= db.view==='Home'?home():db.view==='Experience'?experience():db.view==='Jamaica'?jamaica():db.view==='Lineup'?lineup():db.view==='Tickets'?tickets():db.view==='More'?morePage():db.view==='My Bubbles'?myBubbles():db.view==='Event Guide'?eventGuide():ambassadors();app.insertAdjacentHTML('beforeend','<p class="footer">SKINZ & BUBBLES • PREVIEW • NO LIVE TICKET SALES</p>')};


// V7: My account, reservations-style test cart and My Bubbles; isolated from ambassador/staff state.
if(!db.guests)db.guests=[];
if(!db.guestOrders)db.guestOrders=[];
if(!db.guestSession)db.guestSession=null;
if(!db.guestNotices)db.guestNotices={lineup:true,tickets:true,updates:true};
if(!db.cartQty)db.cartQty=1;
if(!db.guestCheckoutStep)db.guestCheckoutStep='select';
let guestMessage='';
function guestUser(){return (db.guests||[]).find(x=>x.id===db.guestSession)||null}
function guestView(v){db.view=v;guestMessage='';save();render();document.getElementById('app').scrollTo(0,0)}
function guestFormError(msg){guestMessage=msg;render();document.getElementById('guest-error')?.scrollIntoView({block:'nearest'})}
function guestCreate(ev){ev.preventDefault();let f=new FormData(ev.target),name=String(f.get('name')||'').trim(),email=String(f.get('email')||'').trim().toLowerCase(),pass=String(f.get('password')||''),confirm=String(f.get('confirm')||'');if(name.length<2)return guestFormError('Please enter your name.');if(f.get('privacy')!=='on')return guestFormError('Please acknowledge the guest privacy notice.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return guestFormError('Enter a valid email address.');if(pass.length<8)return guestFormError('Use at least 8 characters for your password.');if(pass!==confirm)return guestFormError('Your passwords do not match.');if(db.guests.some(x=>x.email===email))return guestFormError('An account already exists with this email. Please sign in.');if((db.applications||[]).some(a=>a.email===email&&a.username))return guestFormError('This email is registered with the Ambassador Hub. Sign in there using your ambassador username and PIN to access guest tickets.');let id='guest-'+Date.now();db.guests.push({id,name,email,password:pass,marketingOptIn:f.get('marketing')==='on',privacyAcknowledgedAt:new Date().toISOString(),created:new Date().toISOString()});if(db.session){const other=(db.applications||[]).find(a=>a.id===db.session);if(other&&other.email!==email)db.session=null;}db.guestSession=id;guestMessage='';save();guestView(db.pendingTicketCheckout&&db.ticket?'Guest Checkout':'Guest Dashboard');flash('Welcome to My Bubbles, '+name.split(' ')[0]+'!')}
function guestSignIn(ev){ev.preventDefault();let f=new FormData(ev.target),email=String(f.get('email')||'').trim().toLowerCase(),pass=String(f.get('password')||'');let user=db.guests.find(x=>x.email===email&&x.password===pass);if(!user)return guestFormError('Email or password did not match. Please try again.');if(db.session){const other=(db.applications||[]).find(a=>a.id===db.session);if(other&&other.email!==user.email)db.session=null;}db.guestSession=user.id;save();guestView(db.pendingTicketCheckout&&db.ticket?'Guest Checkout':'Guest Dashboard');flash('Welcome back, '+user.name.split(' ')[0])}
function guestSignOut(){db.guestSession=null;save();guestView('Guest Access');flash('You have signed out')}
function guestAccount(){return `<div class="guest-lead"><div class="eyebrow">MY BUBBLES</div><h1>You're invited <em>in.</em></h1><p>Create your account to continue to checkout and keep your tickets in one place.</p></div><div class="guest-filters"><button class="${db.view==='Guest Access'?'on':''}" onclick="guestView('Guest Access')">Create account</button><button onclick="guestView('Guest Login')">Sign in</button></div>${guestMessage?`<div class="guest-error" id="guest-error" role="alert">${E(guestMessage)}</div>`:''}<div class="guest-panel"><h2>Create your account</h2><form onsubmit="guestCreate(event)"><label>Full name<input name="name" autocomplete="name" required minlength="2" placeholder="Your full name"></label><label>Email address<input type="email" name="email" autocomplete="email" required placeholder="you@example.com"></label><label>Password<input type="password" name="password" autocomplete="new-password" minlength="8" required placeholder="At least 8 characters"></label><label>Confirm password<input type="password" name="confirm" autocomplete="new-password" required placeholder="Repeat password"></label><label class="guest-checkbox"><input type="checkbox" name="privacy" required>I acknowledge the Privacy Notice. *</label><label class="guest-checkbox"><input type="checkbox" name="marketing">Email me Skinz & Bubbles news, announcements and ticket offers (optional).</label><button class="btn" style="width:100%" type="submit">CREATE MY BUBBLES ACCOUNT →</button></form><p class="guest-notice">Preview access only: use fictional details and a unique password. This browser does not securely store real accounts.</p></div><div class="guest-status">You can explore tickets without an account. To proceed to checkout, you must create a guest account or sign in. <button class="btn aqua small" onclick="navigate('Tickets')">Explore tickets</button>.</div>`}
function guestLogin(){return `<button class="back" onclick="guestView('Guest Access')">← My account</button><div class="guest-lead"><div class="eyebrow">WELCOME BACK</div><h1>Sign in to <em>My Bubbles</em></h1><p>Your summer in Jamaica starts here.</p></div>${guestMessage?`<div class="guest-error" id="guest-error" role="alert">${E(guestMessage)}</div>`:''}<div class="guest-panel"><form onsubmit="guestSignIn(event)"><label>Email address<input type="email" name="email" autocomplete="email" required placeholder="you@example.com"></label><label>Password<input type="password" name="password" autocomplete="current-password" required placeholder="Your password"></label><button class="btn" type="submit" style="width:100%">SIGN IN →</button></form><p class="guest-notice">Account recovery and access across devices will be available at launch.</p></div>${btn('NEW HERE? CREATE AN ACCOUNT',"guestView('Guest Access')",'aqua')}`}
function guestOrders(){let u=guestUser();return (db.guestOrders||[]).filter(x=>x.guestId===(u?.id||null)&&!!u)}
function guestDashboard(){let u=guestUser();if(!u)return guestAccount();let orders=guestOrders();return `<div class="guest-banner"><div><b>☀ Welcome, ${E(u.name.split(' ')[0])}!</b><div style="font-size:12px;margin-top:4px">Your summer, your way.</div></div><button onclick="guestSignOut()">Sign out</button></div><div class="guest-lead"><div class="eyebrow">YOUR PERSONAL FESTIVAL SPACE</div><h1>My <em>Bubbles</em></h1><p>Find your saved ticket selections, favorites and summer plans in one place.</p><div class="guest-actions">${btn('🎟 EXPLORE TICKETS',"navigate('Tickets')")}${btn('✦ SAVE MOMENTS',"navigate('Experience')",'aqua')}</div></div><div class="guest-tile-grid"><button class="guest-tile" onclick="guestView('Guest Orders')"><span>🎟</span><strong>My Tickets</strong><small>${orders.length} saved selection${orders.length===1?'':'s'}</small></button><button class="guest-tile" onclick="guestView('Guest Favorites')"><span>♡</span><strong>Saved moments</strong><small>${db.favorites.length} favorites</small></button><button class="guest-tile" onclick="guestView('Guest Crew')"><span>👯</span><strong>Bring your crew</strong><small>Invite your friends</small></button><button class="guest-tile" onclick="guestView('Guest Travel')"><span>🌴</span><strong>Jamaica plans</strong><small>Explore the island</small></button><button class="guest-tile" onclick="guestView('Guest Notifications')"><span>🔔</span><strong>Updates</strong><small>Announcement preferences</small></button><button class="guest-tile" onclick="navigate('More')"><span>☰</span><strong>Explore more</strong><small>Lineup, guides, team</small></button></div><div class="guest-panel"><h3>☀ Countdown to Kingston</h3><p><strong>${countdown()} days</strong> to July 31, 2027</p><div class="guest-status">Your saved ticket selections appear under My Tickets. Real paid orders and scannable QR tickets will only be available once Eventin Pro is securely connected.</div></div>`}
function startTicketCheckout(){
 if(!db.ticket)return navigate('Tickets');
 db.pendingTicketCheckout=true; save();
 guestView(guestUser()?'Guest Checkout':'Guest Checkout Gate');
}
function guestCheckoutGate(){
 if(guestUser())return guestCheckout();
 return `<button class="back" onclick="navigate('Tickets')">← Ticket options</button><div class="guest-lead"><div class="eyebrow">ONE MORE STEP</div><h1>Save your <em>tickets</em> in My Bubbles</h1><p>Create an account or sign in to keep your ticket selection in My Tickets.</p></div><div class="guest-panel"><h3>Your selected experience</h3><div class="guest-ticket"><span class="guest-em">🎟</span><div><strong>${E(db.ticket||'Festival ticket')}</strong><small>Kingston, Jamaica • July 31, 2027</small></div></div><div class="guest-actions">${btn('CREATE FREE ACCOUNT →',"guestView('Guest Access')")}${btn('ALREADY HAVE AN ACCOUNT? SIGN IN',"guestView('Guest Login')",'aqua')}</div><p class="guest-notice">An account is required before checkout. Ticket sales are not active yet.</p></div>`;
}
function guestCheckout(){if(!guestUser())return guestCheckoutGate();let n=db.ticket;if(!n)return tickets();let q=Math.max(1,Math.min(10,Number(db.cartQty)||1));return `<button class="back" onclick="navigate('Tickets')">← Ticket experiences</button><div class="guest-lead"><div class="eyebrow">ORDER REVIEW</div><h1>Review your <em>experience.</em></h1><p>Review your selection before continuing. Payments are not available yet.</p></div><div class="guest-steps"><span>1 · Experience ✓</span><span class="current">2 · Review</span><span>3 · Done</span></div><div class="guest-panel"><h2>Order summary</h2><div class="guest-ticket"><span class="guest-em">🎟</span><div><strong>${E(n)}</strong><small>Skinz & Bubbles • July 31, 2027 • Kingston, Jamaica</small></div></div><label>Number of tickets<select id="guestQty" onchange="guestQtyChange(this.value)">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${q===i+1?'selected':''}>${i+1} ${i?'tickets':'ticket'}</option>`).join('')}</select></label><div class="guest-status warn">Prices and fees are not configured in this prototype. We will show the exact final total from your Eventin Pro checkout when connected. No payment information is collected here.</div><div class="guest-actions">${btn('SAVE MY TICKET SELECTION →','completeGuestCheckout()','yellow')}${btn('CHANGE TICKET',"navigate('Tickets')",'ghost')}</div></div>`}
function guestQtyChange(q){db.cartQty=Math.max(1,Math.min(10,Number(q)||1));save()}
function completeGuestCheckout(){if(!guestUser())return guestView('Guest Checkout Gate');if(!db.ticket)return navigate('Tickets');let id='SEL-'+Date.now().toString(36).toUpperCase(),guestId=guestUser()?.id||null,record={id,guestId,type:db.ticket,quantity:db.cartQty,when:new Date().toISOString(),status:'simulation only'};db.guestOrders=db.guestOrders||[];db.guestOrders.unshift(record);db.lastGuestOrder=id;db.pendingTicketCheckout=false;save();guestView('Guest Confirm');}
function guestConfirm(){let o=(db.guestOrders||[]).find(x=>x.id===db.lastGuestOrder);return `<div class="guest-lead" style="text-align:center"><div style="font-size:54px">🫧</div><div class="eyebrow">SELECTION SAVED</div><h1>You're in the <em>Bubbles!</em></h1><p>Your ticket selection has been saved to My Tickets.</p></div><div class="guest-panel"><h3>Your selection</h3><div class="guest-ticket"><span class="guest-em">🎟</span><div><strong>${E(o?.type||db.ticket)}</strong><small>${Number(o?.quantity)||1} selected • ${E(o?.id||'SELECTION')}</small></div></div><div class="guest-status warn"><strong>Not a real purchase.</strong> No money was charged, no booking was made, and this is NOT a valid entry ticket or QR code.</div>${guestUser()?btn('VIEW MY TICKETS',"guestView('Guest Orders')"):`<p>Create a guest account and sign in to continue your ticket selection.</p>${btn('CREATE MY BUBBLES ACCOUNT',"guestView('Guest Access')")}`}${btn('BACK TO HOME',"navigate('Home')",'aqua')}</div>`}
function guestExtras(kind){let u=guestUser();if(!u)return guestLogin();let back=`<button class="back" onclick="guestView('Guest Dashboard')">← My Bubbles</button>`;if(kind==='Guest Orders')return back+`<h1>My <em>Tickets</em></h1><div class="guest-panel"><h3>Your saved ticket selections</h3>${guestOrders().length?guestOrders().map(o=>`<div class="guest-ticket"><span class="guest-em">🎟</span><div><strong>${E(o.type)}</strong><small>${E(o.id)} · ${o.quantity} ticket(s) · NOT A PAID TICKET</small></div></div>`).join(''):'<p>Nothing saved yet. Choose an experience to get started.</p>'}<div class="guest-status warn">These are saved selections, not paid tickets or valid admission codes.</div>${btn('EXPLORE TICKETS',"navigate('Tickets')")}</div>`;if(kind==='Guest Favorites')return back+`<h1>Saved <em>Moments</em></h1><div class="guest-panel">${db.favorites.length?db.favorites.map(x=>`<div class="guest-ticket"><div><strong>${E(x)}</strong></div><button class="btn ghost small" onclick="toggleFavorite(${E(JSON.stringify(x))})">REMOVE</button></div>`).join(''):'<p>Save your favorite experiences from the Experience page.</p>'}${btn('EXPLORE EXPERIENCE',"navigate('Experience')")}</div>`;if(kind==='Guest Crew')return back+`<h1>Bring Your <em>Crew</em></h1><div class="guest-panel"><h3>The party is better together</h3><p>Invite friends to discover Skinz & Bubbles and explore group ticket experiences.</p>${btn('COPY INVITATION','guestInvite()')}${btn('SEE GROUP DEALS','chooseGroup()','aqua')}<div class="guest-status">Invite your friends to plan their Skinz & Bubbles experience. Referral tracking begins when ticketing is connected.</div></div>`;if(kind==='Guest Travel')return back+`<h1>Your <em>Jamaica</em> Plans</h1><div class="guest-panel"><h3>Discover the island</h3><p>Explore Jamaican food, stays, activities and travel information around the festival.</p>${btn('OPEN JAMAICA GUIDE',"navigate('Jamaica')",'aqua')}</div>`;if(kind==='Guest Notifications')return back+`<h1>Festival <em>Updates</em></h1><div class="guest-panel"><h3>Your interests</h3><p>Select the announcements you're interested in.</p>${[['lineup','Music & lineup announcements'],['tickets','Tickets and VIP updates'],['updates','Festival news and safety updates']].map(([id,t])=>`<label style="display:flex;align-items:center;gap:10px"><input style="width:18px;margin:0" type="checkbox" ${db.guestNotices[id]?'checked':''} onchange="guestNotification('${id}',this.checked)">${t}</label>`).join('')}<div class="guest-status">Selections save locally. No push notifications, emails or messages are sent.</div></div>`;return guestDashboard()}
function guestNotification(k,v){db.guestNotices[k]=v;save();flash('Notification preference saved')}
function chooseGroup(){selectTicket('GROUP DEALS');navigate('Tickets')}
function guestInvite(){copyText('Come experience Skinz & Bubbles 2027 with me in Kingston, Jamaica on July 31! Discover the event and group options. (Ticket link will be added when sales open.)')}
const preGuestMorePage=morePage;
morePage=function(){return `<div class="guest-lead"><div class="eyebrow">YOUR SUMMER HUB</div><h2>Explore <em>More</em></h2><p>Everything you need for the Skinz & Bubbles experience.</p></div>${freeButtons([['♡','My Bubbles · Guest Account',"guestView('Guest Dashboard')"],['♫','Music & Lineup',"navigate('Lineup')"],['★','Ambassador Hub',"amb('start')"],['✦','Event Guide & Safety',"navigate('Event Guide')"]])}<div class="guest-panel"><h3>Join the ambassador team</h3><p>Ambassadors, Hosts and Managers use their own separate login area.</p>${btn('OPEN AMBASSADOR HUB',"amb('start')")}</div>`}
const previousGuestHome=home;
home=function(){return previousGuestHome()+`<div class="guest-panel"><div class="eyebrow" style="color:#b42d79">YOUR SUMMER, PERSONALIZED</div><h2>My Bubbles ☀</h2><p>Save your favorite moments, bring your crew and keep track of your ticket plans.</p>${btn(guestUser()?'OPEN MY BUBBLES →':'CREATE YOUR FREE GUEST ACCOUNT →',"guestView('Guest Dashboard')",'aqua')}</div>`}
const previousGuestTickets=tickets;
tickets=function(){return previousGuestTickets().replace("onclick=\"testCheckout()\"","onclick=\"startTicketCheckout()\"")+`<div class="guest-panel"><h3>Already exploring?</h3><p>Browse ticket options freely. Sign up or sign in when you are ready to buy; your order will be saved under My Tickets.</p>${btn(guestUser()?'OPEN MY BUBBLES':'GUEST SIGN IN / SIGN UP',"guestView('Guest Dashboard')",'aqua')}</div>`}
const preGuestRender=render;
render=function(){let guestViews=['Guest Access','Guest Login','Guest Dashboard','Guest Checkout Gate','Guest Checkout','Guest Confirm','Guest Orders','Guest Favorites','Guest Crew','Guest Travel','Guest Notifications'];if(!guestViews.includes(db.view)){preGuestRender();return}preGuestRender();const tabs=[['Home','⌂'],['Experience','✦'],['Jamaica','♧'],['Tickets','🎟'],['More','▦']];document.getElementById('nav').innerHTML=tabs.map(([t,ic])=>`<button class="tab ${t==='More'?'on':''}" onclick="navigate('${t}')" aria-label="${t}"><strong>${ic}</strong>${t}</button>`).join('');let v=db.view;app.innerHTML=(v==='Guest Access'?guestAccount():v==='Guest Login'?guestLogin():v==='Guest Dashboard'?guestDashboard():v==='Guest Checkout Gate'?guestCheckoutGate():v==='Guest Checkout'?guestCheckout():v==='Guest Confirm'?guestConfirm():guestExtras(v))+`<p class="footer">SKINZ & BUBBLES • PREVIEW • NO LIVE TICKET SALES</p>`}


// V9: Ambassadors are also festival guests. Their approved/pending ambassador
// identity gives them a My Bubbles ticket profile in this local prototype.
// The ambassador approval status controls ambassador tools, not guest browsing.
const previousGuestUserV9=guestUser;
guestUser=function(){
  const guest=previousGuestUserV9();
  if(guest)return guest;
  const ambassador=current();
  if(!ambassador)return null;
  return {id:'amb-guest-'+ambassador.id,name:ambassador.name,email:ambassador.email,ambassador:true};
};
function accountHome(){
  const u=guestUser(),a=current(),orders=guestOrders();
  const row=(icon,title,desc,action)=>`<button class="account-clean-link" type="button" onclick="${action}"><span class="account-clean-icon">${icon}</span><span class="account-clean-copy"><strong>${title}</strong><small>${desc}</small></span><span class="account-clean-chevron" aria-hidden="true">›</span></button>`;
  let out=`<section class="account-clean-page"><div class="account-clean-heading"><div class="eyebrow">SKINZ & BUBBLES</div><h1>My Account</h1><p>${u?'Your tickets, profile, and festival plans in one place.':'Sign in to manage your tickets and festival plans.'}</p></div>`;
  if(u){
    out+=`<div class="account-clean-identity"><div class="account-clean-avatar" aria-hidden="true">🫧</div><div><strong>${E(u.name)}</strong><small>${E(u.email)}</small></div></div>`;
    out+=`<section class="account-clean-section"><h2>Your account</h2><div class="account-clean-list">${row('🎫','My Tickets',orders.length?`${orders.length} saved ticket selection${orders.length===1?'':'s'}`:'See your ticket selections',"guestView('Guest Orders')")}${row('✦','Saved Experiences','Your favorite festival moments',"guestView('Guest Favorites')")}${row('🔔','Notifications','Choose which updates you receive',"guestView('Guest Notifications')")}</div></section>`;
    out+=`<section class="account-clean-section"><h2>Festival plans</h2><div class="account-clean-list">${row('🎟','Explore Tickets','View available experiences',"navigate('Tickets')")}${row('🌴','Discover Jamaica','Plan your trip',"navigate('Jamaica')")}</div></section>`;
    if(a){out+=`<section class="account-clean-section"><h2>Ambassador</h2><div class="account-clean-list">${row('★','Ambassador Dashboard','Tasks, resources and account status',"amb('dashboard')")}</div></section>`}
    out+=`<button class="account-clean-signout" type="button" onclick="guestSignOut()">Sign Out</button>`;
  }else{
    out+=`<div class="account-clean-primary"><button class="btn" type="button" onclick="guestView('Guest Access')">Create Account or Sign In</button></div>`;
    out+=`<section class="account-clean-section"><h2>Already an ambassador?</h2><div class="account-clean-list">${row('★','Ambassador Sign In','Use your existing account',"amb('login')")}</div></section>`;
  }
  out+=`<p class="account-clean-note">Ticket purchases and shared accounts will be available when secure checkout is connected. This version is for testing only.</p></section>`;
  return out;
}

