morePage=function(){return `<div class="guest-panel" style="background:linear-gradient(120deg,#edfcff,#fff6fb)"><h3>🫧 My Account</h3><p>Tickets, guest profile and ambassador access, all in one place.</p>${btn('OPEN MY ACCOUNT →',"navigate('Account')")}</div>`+previousMoreV9()};
